/**
 * The simple rating (model rating@1): the score (large), the heading that names it, a line (the count, the
 * scale) and the source as a link. Axes: layout (bar: one row on a card surface from md up, centered: centred,
 * one under the other).
 */
import { type ReactNode } from "react";
import { Block, Box, Container, LinkPlain, Stack, Text, Title } from "../compose";
import { cn, urlOf } from "../utils";

export type RatingSimpleProps = {
  id: string;
  value: string;
  title: string;
  description?: string;
  sourceLabel?: string;
  sourceHref?: string;
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  layout?: "bar" | "centered";
  landmarkLabel?: string;
};

export function RatingSimple({
  id,
  value,
  title,
  description = "",
  sourceLabel = "",
  sourceHref = "",
  level = 2,
  padding = "standard",
  layout = "bar",
  landmarkLabel,
}: RatingSimpleProps) {
  const titleId = id + "-title";
  const box =
    (layout as string) === "bar" ? "flex flex-col gap-4 rounded bg-card p-6 text-card-foreground border border-border md:flex-row md:items-center md:gap-8"
    : "flex flex-col items-center gap-4 text-center";
  const copy = ((layout as string) === "bar") ? "md:grow" : "";
  const copyAlign = ((layout as string) === "bar") ? "start" : "center";
  const copyText = ((layout as string) === "bar") ? "text-start" : "text-center";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="rating-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Box className={box}>
          <Text size="5xl" weight="bold" className="tracking-tight text-primary">
            {value}
          </Text>
          <Stack gap="2" align={copyAlign} className={copy}>
            <Title as={level} size="xl" weight="semibold" className={copyText} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="sm" className={cn("text-muted-foreground", copyText)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          {(sourceLabel && sourceHref) ? (
            <LinkPlain href={urlOf(sourceHref)} className="text-muted-foreground hover:text-foreground">
              <Text size="sm">
                {sourceLabel}
              </Text>
            </LinkPlain>
          ) : null}
        </Box>
      </Container>
    </Block>
  );
}
